import os
import random

r = random.Random(int(os.environ["SEED"]) * 1000 + int(os.environ["INDEX"]))
i = int(os.environ["INDEX"])
def aman(x, d):
    y = abs(x) * 10 ** d
    return abs(y - int(y) - 0.5) > 0.002


while True:
    mutu = r.sample([175, 225, 250, 300, 350, 400], r.randint(1, 4))
    n = r.randint(1, 20)
    data = [(m, m + r.randint(-35, 45)) for m in [r.choice(mutu) for _ in range(n)]]
    if i == 1:
        data = [(m, m) for m, _ in data]
    ok = True
    for m in mutu:
        v = [x for a, x in data if a == m]
        if v and not aman(sum(v) / len(v), 1):
            ok = False
    if ok:
        break
print(n)
for k, (m, x) in enumerate(data, 1):
    print(f'BU-{k:02d}', f'K{m}', x)

